### **OpenID Connect Authorization Endpoint**

This module is responsible for issuing JWT tokens using the OpenID Connect protocol.

```csharp
// OpenIDConnectController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using EnterpriseIAM.Models;

namespace EnterpriseIAM.OpenIDConnect
{
    [ApiController]
    [Route("api/[controller]")]
    public class OpenIDConnectController : ControllerBase
    {
        private readonly IConfiguration _configuration;
        private readonly IUserDirectoryService _userDirectoryService;

        public OpenIDConnectController(IConfiguration configuration, IUserDirectoryService userDirectoryService)
        {
            _configuration = configuration;
            _userDirectoryService = userDirectoryService;
        }

        [HttpPost("token")]
        public async Task<IActionResult> GetToken([FromBody] TokenRequest request)
        {
            // Authenticate the user
            var user = await _userDirectoryService.GetUser(request.Username);
            if (user == null || !await _userDirectoryService.VerifyPassword(user, request.Password))
            {
                return Unauthorized();
            }

            // Generate JWT token
            var tokenHandler = new JwtSecurityTokenHandler();
            var key = Encoding.ASCII.GetBytes(_configuration["SecretKey"]);
            var tokenDescriptor = new SecurityTokenDescriptor
            {
                Subject = new ClaimsIdentity(new[] { new Claim("id", user.Id) }),
                Expires = DateTime.UtcNow.AddHours(1),
                SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature)
            };
            var token = tokenHandler.CreateToken(tokenDescriptor);
            var tokenString = tokenHandler.WriteToken(token);

            return Ok(new { access_token = tokenString });
        }
    }

    // TokenRequest.cs
    public class TokenRequest
    {
        public string Username { get; set; }
        public string Password { get; set; }
    }
}
```

### **User Directory Service**

This module manages password hashing and account locking.

```csharp
// UserDirectoryService.cs
using System.Security.Cryptography;
using System.Text;
using EnterpriseIAM.Models;

namespace EnterpriseIAM.UserDirectoryService
{
    public interface IUserDirectoryService
    {
        Task<User> GetUser(string username);
        Task<bool> VerifyPassword(User user, string password);
        Task<bool> CreateUser(string username, string email, string password);
    }

    public class UserDirectoryService : IUserDirectoryService
    {
        private readonly IUserRepository _userRepository;

        public UserDirectoryService(IUserRepository userRepository)
        {
            _userRepository = userRepository;
        }

        public async Task<User> GetUser(string username)
        {
            return await _userRepository.GetUser(username);
        }

        public async Task<bool> VerifyPassword(User user, string password)
        {
            var passwordHash = await HashPassword(password, user.PasswordHash);
            return passwordHash.Equals(user.PasswordHash);
        }

        public async Task<bool> CreateUser(string username, string email, string password)
        {
            var hashedPassword = await HashPassword(password);
            var user = new User { Username = username, Email = email, PasswordHash = hashedPassword };
            await _userRepository.CreateUser(user);
            return true;
        }

        private async Task<string> HashPassword(string password)
        {
            using var sha256 = SHA256.Create();
            var hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            var hashedPassword = BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
            return hashedPassword;
        }

        private async Task<string> HashPassword(string password, string salt)
        {
            using var sha256 = SHA256.Create();
            var saltedPassword = password + salt;
            var hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(saltedPassword));
            var hashedPassword = BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
            return hashedPassword;
        }
    }

