### **Utilities**

To use the utilities, you need to add them to your project.

```csharp
// JwtTokenValidator.cs
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.Tokens;

namespace EnterpriseIAM.Utilities
{
    public interface IJwtTokenValidator
    {
        bool ValidateToken(string token);
    }

    public class JwtTokenValidator : IJwtTokenValidator
    {
        private readonly string _secretKey;

        public JwtTokenValidator(string secretKey)
        {
            _secretKey = secretKey;
        }

        public bool ValidateToken(string token)
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            try
            {
                tokenHandler.ValidateToken(token, new TokenValidationParameters
                {
                    ValidateIssuerSigningKey = true,
                    IssuerSigningKey = new SymmetricSecurityKey(Encoding.ASCII.GetBytes(_secretKey)),
                    ValidateIssuer = false,
                    ValidateAudience = false,
                    ClockSkew = TimeSpan.Zero
                }, out var validatedToken);

                return true;
            }
            catch (SecurityTokenException)
            {
                return false;
            }
        }
    }
}
```

### **Main Program**

Create an instance of the `Program` class to start the application.

```csharp
// Program.cs
using EnterpriseIAM.OpenIDConnect;
using EnterpriseIAM.TokenRevocationSubsystem;
using EnterpriseIAM.Utilities;
using EnterpriseIAM.UserDirectoryService;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseIAM
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var configuration = new ConfigurationBuilder()
                .AddJsonFile("appsettings.json")
                .Build();

            var openidConnectController = new OpenIDConnectController(configuration, new UserDirectoryService(new UserRepository()));
            var tokenRevocationSubsystem = new TokenRevocationSubsystem(new BlacklistedTokenRepository());

            // Use the services
            var tokenRequest = new TokenRequest { Username = "username", Password = "password" };
            var tokenResponse = openidConnectController.GetToken(tokenRequest);
            if (tokenResponse != null && (tokenResponse.Result as OkObjectResult)?.StatusCode == 200)
            {
                var token = (tokenResponse.Result as OkObjectResult)?.Value as dynamic;
                tokenRevocationSubsystem.AddBlacklistedToken(new Token { Value = token.access_token });
            }

            var tokenValidator = new JwtTokenValidator(configuration["SecretKey"]);
            var isValidToken = tokenValidator.ValidateToken(token.access_token);
            Console.WriteLine($"Is token valid: {isValidToken}");
        }
    }
}
```

